CREATE TABLE "agent_base_prompts" (
  "agent" text,
  "prompt" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("agent")
);

CREATE TABLE "agent_executions" (
  "id" text,
  "body" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("id")
);

CREATE INDEX "agent_executions_ended" ON "agent_executions" ((body::JSON ->> 'endedAt'));

CREATE TABLE "agent_log" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "agent" text NOT NULL,
  "run" text NOT NULL,
  "chat_id" bigint,
  "at" bigint NOT NULL,
  "kind" text NOT NULL,
  "name" text,
  "parent" text,
  "ref" text,
  "truncated" bigint NOT NULL DEFAULT 0,
  "text" text NOT NULL,
  "job_id" bigint,
  "sequence" bigint,
  "source" text,
  "source_event" bigint,
  "source_block" bigint,
  "source_id" text,
  "state" text,
  "upstream_truncated" bigint NOT NULL DEFAULT 0,
  "detail_complete" bigint NOT NULL DEFAULT 0,
  "detail_length" bigint NOT NULL DEFAULT 0,
  "metadata_length" bigint NOT NULL DEFAULT 0,
  "detail" text,
  "metadata" text,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE INDEX "agent_log_agent" ON "agent_log" (agent, id);

CREATE INDEX "agent_log_at" ON "agent_log" (at);

CREATE INDEX "agent_log_job" ON "agent_log" (job_id, id);

CREATE UNIQUE INDEX "agent_log_job_sequence" ON "agent_log" (job_id, sequence) WHERE job_id IS NOT NULL;

CREATE INDEX "agent_log_run" ON "agent_log" (agent, run, id);

CREATE INDEX IF NOT EXISTS "agent_log_prompts" ON "agent_log" (agent, name, id) WHERE kind = 'prompt';

CREATE TABLE "agents" (
  "name" text,
  "kind" text NOT NULL,
  "account" text,
  "last_mode" text,
  "last_model" text,
  "last_effort" text,
  "chat_id" bigint,
  "session_id" text,
  "last_run_at" bigint,
  "last_keepalive_at" bigint,
  "keepalive_stopped" bigint NOT NULL DEFAULT 0,
  "runs" bigint NOT NULL DEFAULT 0,
  "keepalive_paused_at" bigint,
  "context_tokens" bigint,
  "prompt_changed_at" bigint,
  "label" text,
  "aliases" text,
  "icon" text,
  "cwd" text,
  "builtin" bigint NOT NULL DEFAULT 0,
  "preamble" text,
  "dev_command" text,
  "downgrade_heal" bigint NOT NULL DEFAULT 1,
  "support_count" bigint NOT NULL DEFAULT 0,
  "support_keepalive" bigint NOT NULL DEFAULT 0,
  "support_of" text,
  "support_slot" bigint,
  "pinned_provider" text,
  "item_worker" text,
  "herdr_label" text,
  "resting_since" bigint,
  "pinned_model" text,
  "thinking" bigint,
  "effort" text,
  "brain_folder" text,
  "voice" text,
  "window_seconds" bigint,
  "wake_words" text,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "node" text,
  "role" text,
  "session_scope" text,
  "turn_shape" text,
  "default_answerer" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("name")
);

CREATE TABLE "base_prompt_changes" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "prompt" text,
  "agent" text,
  "field" text NOT NULL,
  "value_before" text,
  "value_after" text,
  "changed_by" text NOT NULL,
  "at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE TABLE "base_prompts" (
  "name" text,
  "label" text NOT NULL,
  "text" text NOT NULL,
  "updated_at" bigint,
  "updated_by" text,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("name")
);

CREATE TABLE "branch_agents" (
  "pool" text NOT NULL DEFAULT '',
  "slot" bigint NOT NULL,
  "mode" text NOT NULL,
  "model" text NOT NULL,
  "role" text NOT NULL,
  "upstream" text NOT NULL DEFAULT '',
  "prefix_digest" text NOT NULL DEFAULT '',
  "last_reply_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("pool", "slot", "mode", "model", "upstream")
);

CREATE TABLE "claude_accounts" (
  "id" text,
  "name" text NOT NULL,
  "place" bigint NOT NULL,
  "enabled" bigint NOT NULL DEFAULT 1,
  "credential_kind" text NOT NULL,
  "credential_path" text NOT NULL,
  "added_at" bigint NOT NULL,
  "needs_login_at" bigint,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "user_id" bigint,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "claude_accounts_name" ON "claude_accounts" (name);

CREATE TABLE "companion_setting_changes" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "agent" text NOT NULL,
  "field" text NOT NULL,
  "value_before" text,
  "value_after" text,
  "changed_by" text NOT NULL,
  "at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE INDEX "companion_setting_changes_agent" ON "companion_setting_changes" (agent, id);

CREATE TABLE "companion_settings" (
  "agent" text,
  "reference_on" bigint,
  "pieces" text,
  "own_pieces" text,
  "persona" text,
  "tools" text,
  "updated_at" bigint,
  "updated_by" text,
  "generation" text,
  "recollector_model" text,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "saved_settings" text,
  PRIMARY KEY ("agent")
);

CREATE TABLE "coworker_pool_limits" (
  "provider" text NOT NULL,
  "model" text NOT NULL,
  "effort" text NOT NULL,
  "capacity" bigint NOT NULL,
  "label" text NOT NULL,
  "set_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("provider", "model", "effort")
);

CREATE TABLE "coworker_pool_meta" (
  "version" bigint GENERATED BY DEFAULT AS IDENTITY,
  rowid bigint GENERATED ALWAYS AS ("version") STORED,
  PRIMARY KEY ("version")
);

CREATE TABLE "coworker_pool_native" (
  "token" text,
  "session" text NOT NULL,
  "tool_use_id" text NOT NULL,
  "waiter_pid" bigint NOT NULL,
  "waiter_start" text NOT NULL,
  "owner_pid" bigint NOT NULL,
  "owner_start" text NOT NULL,
  "agent_id" text,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("token"),
  UNIQUE ("session", "tool_use_id")
);

CREATE TABLE "coworker_pool_native_reservations" (
  "token" text,
  "owner_pid" bigint NOT NULL,
  "owner_start" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("token")
);

CREATE TABLE "coworker_pool_native_stops" (
  "agent_id" text,
  "at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("agent_id")
);

CREATE TABLE "coworker_pool_pings" (
  "reservation" text NOT NULL,
  "place" text NOT NULL,
  "provider" text NOT NULL,
  "model" text NOT NULL,
  "at" bigint NOT NULL,
  "outcome" text NOT NULL,
  "answered_at" bigint,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("reservation", "place")
);

CREATE TABLE "coworker_pool_place_writes" (
  "place" text,
  "provider" text NOT NULL,
  "model" text NOT NULL,
  "effort" text NOT NULL,
  "upstream" text,
  "written_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("place")
);

CREATE TABLE "coworker_pool_requests" (
  "sequence" bigint GENERATED BY DEFAULT AS IDENTITY,
  "token" text NOT NULL,
  "request_key" text NOT NULL,
  "owner" text NOT NULL,
  "source" text NOT NULL,
  "role" text NOT NULL,
  "work_key" text NOT NULL,
  "provider" text NOT NULL,
  "model" text NOT NULL,
  "effort" text NOT NULL,
  "tier" text NOT NULL,
  "capacity" bigint NOT NULL,
  "generation" bigint NOT NULL,
  "state" text NOT NULL,
  "enqueued_at" bigint NOT NULL,
  "leased_at" bigint,
  "child_id" text,
  "ended_at" bigint,
  "outcome" text,
  "reservation" text,
  "class" text NOT NULL DEFAULT 'foreground',
  "place_key" text,
  "turn" bigint NOT NULL DEFAULT 0,
  rowid bigint GENERATED ALWAYS AS ("sequence") STORED,
  PRIMARY KEY ("sequence"),
  UNIQUE ("request_key"),
  UNIQUE ("token")
);

CREATE INDEX "coworker_pool_class_waiting" ON "coworker_pool_requests" (provider, tier, state, class, sequence);

CREATE INDEX "coworker_pool_owner" ON "coworker_pool_requests" (owner, state, sequence);

CREATE INDEX "coworker_pool_place_keys" ON "coworker_pool_requests" (place_key, state);

CREATE INDEX "coworker_pool_seats" ON "coworker_pool_requests" (reservation, state, sequence);

CREATE INDEX "coworker_pool_tier_waiting" ON "coworker_pool_requests" (provider, tier, state, sequence);

CREATE INDEX "coworker_pool_waiting" ON "coworker_pool_requests" (provider, model, effort, state, sequence);

CREATE TABLE "coworker_pool_reservation_meta" (
  "version" bigint GENERATED BY DEFAULT AS IDENTITY,
  rowid bigint GENERATED ALWAYS AS ("version") STORED,
  PRIMARY KEY ("version")
);

CREATE TABLE "coworker_pool_reservations" (
  "token" text,
  "reservation_key" text NOT NULL,
  "owner" text NOT NULL,
  "source" text NOT NULL,
  "role" text NOT NULL,
  "work_key" text NOT NULL,
  "provider" text NOT NULL,
  "model" text NOT NULL,
  "effort" text NOT NULL,
  "tier" text NOT NULL,
  "wanted" bigint NOT NULL,
  "state" text NOT NULL,
  "created_at" bigint NOT NULL,
  "ended_at" bigint,
  "outcome" text,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("token"),
  UNIQUE ("reservation_key")
);

CREATE INDEX "coworker_pool_reservation_owner" ON "coworker_pool_reservations" (owner, state);

CREATE TABLE "coworker_pool_roles" (
  "name" text,
  "description" text NOT NULL,
  "prompt" text NOT NULL,
  "tools" text NOT NULL,
  "skills" text NOT NULL,
  "enabled" bigint NOT NULL,
  "pooled" bigint NOT NULL,
  "set_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("name")
);

CREATE TABLE "coworker_pool_tier_limits" (
  "provider" text NOT NULL,
  "tier" text NOT NULL,
  "capacity" bigint NOT NULL,
  "set_at" bigint NOT NULL,
