);

CREATE TABLE "fallback_routes" (
  "key" text,
  "account" text,
  "claude_model" text,
  "j3090_model" text,
  "codex_model" text,
  "codex_effort" text,
  "openrouter_model" text,
  "set_at" bigint NOT NULL,
  "route_mode" text NOT NULL DEFAULT 'auto',
  "forced" bigint NOT NULL DEFAULT 0,
  "j3090_thinking" bigint,
