  "what" text NOT NULL,
  "ran_at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE INDEX "live_claude_runs_opening" ON "live_claude_runs" (opening_id);

CREATE TABLE "model_catalogue" (
  "name" text,
