  "temperature" double precision,
  "top_p" double precision,
  "presence_penalty" double precision,
  "max_tokens" bigint,
  "note" text,
  "added_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("name")
);

CREATE TABLE "model_fallbacks" (
  "model" text,
  "openrouter_model" text NOT NULL,
  "set_at" bigint NOT NULL,
  "forced" bigint NOT NULL DEFAULT 0,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("model")
);

CREATE TABLE "model_tier_assignments" (
  "key" text,
  "tier" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("key")
);

CREATE TABLE "model_tier_backfilled" (
  "key" text,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("key")
);

CREATE TABLE "model_tier_conflicts" (
  "key" text NOT NULL,
  "provider" text NOT NULL,
  "previous" text NOT NULL,
  "accepted" bigint NOT NULL DEFAULT 0,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("key", "provider")
);

CREATE TABLE "model_tier_legacy" (
  "key" text,
  "body" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("key")
);

CREATE TABLE "model_tier_mappings" (
  "provider" text NOT NULL,
  "tier" text NOT NULL,
  "model" text NOT NULL,
  "effort" text,
  "answer_tokens" bigint,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("provider", "tier")
);

CREATE TABLE "model_tier_meta" (
  "version" bigint GENERATED BY DEFAULT AS IDENTITY,
  rowid bigint GENERATED ALWAYS AS ("version") STORED,
  PRIMARY KEY ("version")
);

CREATE TABLE "model_tier_seeded" (
  "provider" text,
