  PRIMARY KEY ("provider")
);

CREATE TABLE "model_uses" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "entry" text NOT NULL,
  "engine" text NOT NULL,
  "chosen_by" text NOT NULL,
  "started_at" bigint NOT NULL,
  "ended_at" bigint,
  "state" text NOT NULL,
  "step" text,
  "reason" text,
  "log" text,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "node_assignments" ("node" text NOT NULL,"kind" text NOT NULL,"count" bigint NOT NULL DEFAULT 0,"last_at" bigint, rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE, PRIMARY KEY ("node","kind"));

CREATE TABLE "node_hubs" (
  "url" text,
  "token_file" text NOT NULL,
  "created_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("url")
);

CREATE TABLE IF NOT EXISTS "node_rotation" ("rotation" text NOT NULL PRIMARY KEY,"last_node" text NOT NULL,"updated_at" bigint NOT NULL, rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE IF NOT EXISTS "node_workplaces" ("node" text NOT NULL PRIMARY KEY,"root" text NOT NULL,"home" text,"runs" bigint NOT NULL DEFAULT 0,"state" text NOT NULL DEFAULT 'unknown',"detail" text,"checked_at" bigint,"created_at" bigint NOT NULL,"updated_at" bigint NOT NULL, rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE);

CREATE TABLE "prefix_moves" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "agent" text NOT NULL,
  "at" bigint NOT NULL,
  "why" text NOT NULL,
  "detail" text,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE INDEX "prefix_moves_at" ON "prefix_moves" (at);

CREATE TABLE "registered_model_addresses" (
  "registration" text NOT NULL,
  "node" text NOT NULL,
  "position" bigint NOT NULL,
  "url" text NOT NULL,
  "key_file" text,
  "key_owned" bigint NOT NULL DEFAULT 0,
  "placed_at" bigint,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("registration", "node")
);

CREATE TABLE "registered_models" (
  "name" text,
  "label" text NOT NULL,
  "model" text NOT NULL,
  "context_tokens" bigint NOT NULL,
  "answer_tokens" bigint NOT NULL,
  "wait_seconds" bigint NOT NULL,
  "thinking" bigint NOT NULL,
  "walked" bigint NOT NULL,
  "added_at" bigint NOT NULL,
  "keeps_research" bigint NOT NULL DEFAULT 0,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("name")
);

CREATE TABLE "room_session_turns" (
  "agent" text NOT NULL,
  "chat_id" bigint NOT NULL,
  "generation" bigint NOT NULL,
  "position" bigint NOT NULL,
  "role" text NOT NULL,
  "text" text NOT NULL,
  "at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("agent", "chat_id", "generation", "position")
);

CREATE TABLE "room_sessions" (
  "agent" text NOT NULL,
  "chat_id" bigint NOT NULL,
  "generation" bigint NOT NULL,
  "opened_at" bigint NOT NULL,
  "last_message_id" bigint,
  "system_hash" text,
  "system_reset_at" bigint,
  "harness_session" text,
  "harness_road" text,
  "placement" text,
  "handoff_note" text,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  "spent_calls" bigint NOT NULL DEFAULT 0,
  "spent_ms" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("agent", "chat_id")
);

CREATE TABLE "room_windows" (
  "chat_id" bigint NOT NULL,
  "agent" text NOT NULL,
  "open_until" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("chat_id", "agent")
);

CREATE TABLE "run_records" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "run" text NOT NULL,
  "kind" text NOT NULL,
  "text" text NOT NULL,
  "record_id" bigint,
  "wakes" bigint NOT NULL DEFAULT 0,
  "at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE INDEX "run_records_run" ON "run_records" (run, id);

CREATE TABLE "session_resets" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "agent" text NOT NULL,
  "chat_id" bigint,
  "asked_by" text NOT NULL,
  "asked_at" bigint NOT NULL,
  "reason" text NOT NULL,
  "done_at" bigint,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE INDEX "session_resets_agent" ON "session_resets" (agent, chat_id, id);

CREATE TABLE "settings" (
  "key" text,
  "value" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("key")
);

CREATE TABLE "worker_sessions" (
  "worker" text NOT NULL DEFAULT 'worker',
  "model" text NOT NULL,
  "account" text NOT NULL DEFAULT 'default',
  "claude_session_id" text NOT NULL,
  "last_reply_at" bigint NOT NULL,
  "prefix_digest" text,
  "answered_model" text,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("worker", "model", "account")
);
